/**
 * Form-rules engine — runs public/catalog/form_rules.json (generated by scripts/extract-form-rules.py).
 * One engine for every DocType: depends_on / mandatory_depends_on / read_only_depends_on, fetch_from,
 * ported form-script statements (toggle_display/reqd/enable, set_df_property, set_value, child set_value)
 * and calculation profiles (src/lib/formCalc.ts). Expressions go through the controlled interpreter (expr.ts).
 * Rules marked server (they read server callback data) are never applied.
 */
import { queryOptions } from "@tanstack/react-query";
import { t } from "@/i18n";
import { adapter, type Doc } from "./adapter";
import type { DocField, DocTypeMeta } from "./catalog";
import { evalExpr, evalDependsSafe } from "./expr";
import { runCalc, calcValidate, type CalcRule } from "./formCalc";
import { defaultTaxTemplate, isItemTable, itemRowPatch, priceListPatch, templateTaxes, uomRowPatch } from "./itemDetails";

export interface FormRule {
  id: string; kind: string; fields: string[]; value?: string; cond?: string | null; trigger?: string; triggers?: string[];
  load?: boolean; child?: string; server?: number; link?: string; source_field?: string; if_empty?: number;
  profile?: string; items?: string; has_rounding?: number; has_in_words?: number; src: string;
}
export type RuleMap = Record<string, FormRule[]>;
export const formRulesQuery = queryOptions({
  queryKey: ["catalog-form-rules"],
  queryFn: async () => ((await (await fetch("/catalog/form_rules.json")).json()) as { doctypes: RuleMap }).doctypes,
  staleTime: Infinity,
});

export type Over = Record<string, { hidden?: boolean; reqd?: boolean; ro?: boolean }>;
export interface FormState { doc: Doc; over: Over; applied: string[] }

const truthy = (v: unknown) => (Array.isArray(v) ? v.length > 0 : !!v);
function ev(expr: string | null | undefined, doc: Doc, row?: Doc): { v: unknown; ok: boolean } {
  if (expr == null || expr === "") return { v: true, ok: true };
  const r = evalExpr(expr, doc, row ? { row } : undefined);
  return { v: r.value, ok: r.supported };
}
const UI_KINDS = new Set(["toggle_display", "toggle_reqd", "toggle_enable", "df_hidden", "df_reqd", "df_read_only"]);

/** Applies one UI rule to the override map; returns false when not applicable (cond false / unsupported). */
function applyUi(r: FormRule, doc: Doc, over: Over): boolean {
  const c = ev(r.cond, doc); if (!c.ok || !truthy(c.v)) return false;
  const v = ev(r.value ?? "true", doc); if (!v.ok) return false;
  const b = truthy(v.v);
  for (const f of r.fields) {
    const o = (over[f] = { ...over[f] });
    if (r.kind === "toggle_display") o.hidden = !b; else if (r.kind === "df_hidden") o.hidden = b;
    else if (r.kind === "toggle_reqd" || r.kind === "df_reqd") o.reqd = b;
    else if (r.kind === "toggle_enable") o.ro = !b; else if (r.kind === "df_read_only") o.ro = b;
  }
  return true;
}

function calcAll(rules: FormRule[], doc: Doc): Doc {
  let d = doc;
  for (const r of rules) if (r.kind === "calc") d = runCalc(d, r as unknown as CalcRule);
  return d;
}

/** Initial state on form load: refresh/onload/setup UI statements + calculations. */
export function loadState(rules: FormRule[] | undefined, doc: Doc): FormState {
  const over: Over = {}; const applied: string[] = [];
  for (const r of rules ?? []) if (r.load && !r.server && !r.child && UI_KINDS.has(r.kind) && applyUi(r, doc, over)) applied.push(r.id);
  return { doc, over, applied };
}

function diffRows(prev: Doc[] | undefined, next: Doc[]): { row: Doc; idx: number; fields: string[]; added: boolean }[] {
  const out: { row: Doc; idx: number; fields: string[]; added: boolean }[] = [];
  next.forEach((row, i) => {
    const p = prev?.find((x) => x.name === row.name) ?? (prev && prev.length === next.length ? prev[i] : undefined);
    if (!p) { out.push({ row, idx: i, fields: Object.keys(row), added: true }); return; }
    const fs = Object.keys(row).filter((k) => JSON.stringify(row[k]) !== JSON.stringify(p[k]));
    if (fs.length) out.push({ row, idx: i, fields: fs, added: false });
  });
  return out;
}

/**
 * Field change → new state. Runs fetch_from for changed links, form-script statements whose trigger handlers
 * are reached by the changed field (or `<table>_add` for new rows), cascades set_value changes (max 6 passes),
 * then recomputes calculation profiles.
 */
export function applyChange(meta: DocTypeMeta, rules: FormRule[] | undefined, st: FormState, patch: Record<string, unknown>): FormState {
  const rs = rules ?? [];
  let doc: Doc = { ...st.doc, ...patch };
  const over: Over = { ...st.over }; const applied = [...st.applied];
  let changed = Object.keys(patch); let prev = st.doc;
  for (let pass = 0; pass < 6 && changed.length; pass++) {
    const next: Record<string, unknown> = {};
    for (const f of changed) {
      // fetch_from (frappe form/script_manager: link field change fetches dependent values)
      for (const r of rs) if (r.kind === "fetch_from" && r.link === f) {
        const link = meta.fields.find((x) => x.fieldname === f);
        if (!link?.options) continue;
        const tdt = link.fieldtype === "Dynamic Link" ? String(doc[link.options] || "") : link.options;
        const tgt = doc[f] ? adapter.get(tdt, String(doc[f])) : undefined;
        const tf = r.fields[0]!;
        if (r.if_empty && doc[tf]) continue;
        next[tf] = tgt ? (tgt[r.source_field!] ?? "") : ""; applied.push(r.id);
      }
      // owner note 6 LINK-03: a tax template choice copies its tax rows (transaction.js taxes_and_charges)
      if (f === "taxes_and_charges" && meta.fields.some((x) => x.fieldname === "taxes")) { const tx = templateTaxes(doc, String(doc[f] ?? "")); if (tx) { next["taxes"] = tx; applied.push("item_details:taxes"); } }
      for (const r of rs) {
        if (r.server || r.child || !r.triggers?.includes(f)) continue;
        if (UI_KINDS.has(r.kind)) { if (applyUi(r, doc, over)) applied.push(r.id); }
        else if (r.kind === "set_value") {
          const c = ev(r.cond, doc); if (!c.ok || !truthy(c.v)) continue;
          const v = ev(r.value, doc); if (!v.ok) continue;
          if (JSON.stringify(doc[r.fields[0]!]) !== JSON.stringify(v.v)) next[r.fields[0]!] = v.v;
          applied.push(r.id);
        }
      }
      // child-table events (frappe.ui.form.on("<Child DocType>", { field(frm, cdt, cdn) }))
      const tf = meta.fields.find((x) => x.fieldname === f && (x.fieldtype === "Table" || x.fieldtype === "Table MultiSelect"));
      if (tf && Array.isArray(doc[f])) {
        const rowsNext = (doc[f] as Doc[]).map((x) => ({ ...x }));
        let touched = false;
        const items = isItemTable(meta.name, tf.options!);
        for (const ch of diffRows(prev[f] as Doc[] | undefined, rowsNext)) {
          const trig = ch.added ? [`${f}_add`, ...ch.fields] : ch.fields;
          // owner note 6 LINK-02: choosing an item fills the row (get_item_details); a unit change re-reads factor and price
          if (items) {
            const row = rowsNext[ch.idx]!;
            const p = ch.fields.includes("item_code") ? itemRowPatch(doc, tf.options!, row) : ch.fields.includes("uom") ? uomRowPatch(doc, tf.options!, row) : {};
            if (Object.keys(p).length) { Object.assign(row, p); touched = true; applied.push("item_details"); }
            // the price list that priced the row becomes the document's when it has none (set_price_list_currency)
            if (ch.fields.includes("item_code") && p["price_list_rate"] !== undefined) Object.assign(next, priceListPatch(meta, doc));
          }
          for (const r of rs) {
            if (r.server || r.child !== tf.options || r.kind !== "row_set_value" || !r.triggers?.some((t) => trig.includes(t))) continue;
            const row = rowsNext[ch.idx]!;
            const c = ev(r.cond, doc, row); if (!c.ok || !truthy(c.v)) continue;
            const v = ev(r.value, doc, row); if (!v.ok) continue;
            row[r.fields[0]!] = v.v; touched = true; applied.push(r.id);
          }
        }
        if (touched) doc = { ...doc, [f]: rowsNext };
        // LINK-03: the first chosen item brings the company's default tax template when the document has none yet
        if (items && f === "items" && !doc["taxes_and_charges"] && !(Array.isArray(doc["taxes"]) && (doc["taxes"] as Doc[]).length)
          && !((prev[f] as Doc[] | undefined) ?? []).some((x) => x["item_code"] && adapter.get("Item", String(x["item_code"]))) && rowsNext.some((x) => x["item_code"] && adapter.get("Item", String(x["item_code"])))
          && meta.fields.some((x) => x.fieldname === "taxes_and_charges") && meta.fields.some((x) => x.fieldname === "taxes")) {
          const tpl = defaultTaxTemplate(doc); const tx = tpl ? templateTaxes(doc, tpl) : null;
          if (tpl && tx) { next["taxes_and_charges"] = tpl; doc = { ...doc, taxes: tx }; applied.push("item_details:default_taxes"); }
        }
      }
    }
    prev = doc;
    doc = { ...doc, ...next };
    changed = Object.keys(next);
  }
  doc = calcAll(rs, doc);
  return { doc, over, applied };
}

/** Effective field state: static df + *_depends_on + ported form-script overrides. */
export function fieldState(f: DocField, doc: Doc, over: Over | undefined) {
  const o = (f.fieldname && over?.[f.fieldname]) || {};
  const hidden = o.hidden ?? (!!f.hidden || !evalDependsSafe(f.depends_on, doc).value);
  const reqd = o.reqd ?? (!!f.reqd || (!!f.mandatory_depends_on && evalDependsSafe(f.mandatory_depends_on, doc).value));
  const ro = o.ro ?? (!!f.read_only || (!!f.read_only_depends_on && evalDependsSafe(f.read_only_depends_on, doc).value));
  return { hidden, reqd, ro };
}

const EMPTY = (v: unknown) => v === undefined || v === null || v === "" || (Array.isArray(v) && v.length === 0);
const NOVAL = new Set(["Section Break", "Column Break", "Tab Break", "HTML", "Button", "Fold", "Heading", "Image"]);
/** Mandatory fields still empty (frappe form/save.js check_mandatory), shared by Save validation and the form's next-step guide. */
export function missingMandatory(meta: DocTypeMeta, st: Pick<FormState, "doc" | "over">) {
  return meta.fields.filter((f) => f.fieldname && f.fieldname !== "naming_series" && (f as { default?: unknown }).default === undefined && !NOVAL.has(f.fieldtype) && f.fieldtype !== "Check" && fieldState(f, st.doc, st.over).reqd && !fieldState(f, st.doc, st.over).hidden && EMPTY(st.doc[f.fieldname]));
}
/** Save-time validation: mandatory fields (frappe form/save.js check_mandatory) + ported controller validations. */
export function validateDoc(meta: DocTypeMeta, rules: FormRule[] | undefined, st: FormState): string[] {
  // naming_series is filled by the server autoname; fields with a source default get it on new documents (frappe.model.get_new_doc)
  const missing = missingMandatory(meta, st)
    .map((f) => f.label || f.fieldname!);
  const out = missing.length ? [`${t("Missing Fields")}: ${missing.map((m) => t(m, meta.name)).join(t("Missing Fields") === "Missing Fields" ? ", " : "، ")}`] : [];
  for (const r of rules ?? []) if (r.kind === "calc") out.push(...calcValidate(st.doc, r as unknown as CalcRule));
  return out;
}
